def card(item):
 b=item['badge']; return f'''<article class="card" id="{item['id']}"><h2>{item['title']}</h2><div class="badges"><span class="badge {b[0]}">{b[1]}</span><span class="badge spec">{item['tag']}</span></div><ul class="facts"><li>Source: <a href="{item['url']}">{item['source']}</a></li><li>Signal: {item['signal']}</li></ul><h3>What it is</h3><div>{item['what']}</div><h3>Why it matters</h3><div>{item['why']}</div><h3>Buildn / client use</h3><div>{item['use']}</div><ul class="wins">{''.join('<li>'+x+'</li>' for x in item['wins'])}</ul><div class="callout"><strong>Caveat / next move:</strong> {item['next']}</div></article>'''
def report(lane, thesis, kind, items, matrix, actions):
 sources=''.join(f'<li><a href="{x["url"]}">{x["title"]}</a> <span class="small">— {x.get("typ")}</span></li>' for x in items)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Ingest — {lane}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:wght@400;500;600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{CSS}</head><body><main><header><div class="wordmark">{logo}<span>Buildn</span></div><div class="date">Daily Ingest Dossier · {DATE}</div><h1>{lane}</h1><div class="lede">{thesis}</div></header><section class="card"><h2>Signal map</h2><div class="signal"><div><strong>Observe</strong><span class="small">{items[0]['map']}</span></div><div><strong>Connect</strong><span class="small">{items[1]['map']}</span></div><div><strong>Try</strong><span class="small">{items[2]['map']}</span></div></div><div class="diagram">{svg(kind)}</div></section><section class="section"><div class="grid">{''.join(card(x) for x in items)}</div></section><section class="section card"><h2>Use-case matrix</h2><table class="matrix"><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr>{''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in matrix)}</table></section><section class="section card top"><h2>Top actions</h2><ol class="wins">{''.join('<li>'+a+'</li>' for a in actions)}</ol></section><section class="section card"><h2>Source trail</h2><ol class="source-list">{sources}</ol></section></main></body></html>'''

